free = []
for n in [1, 2, 3, 4]:
    try:
        if n % 2 == 0:
            raise ValueError("taken")
        free.append(n)
    except ValueError:
        pass
print(free)

class Counter:
    def __init__(self):
        self.n = 0
    def add(self):
        self.n += 1
    def __len__(self):
        return self.n
c = Counter(); c.add(); c.add()
print(len(c))

